while (west_remaining > 0) {
    x = 1552 - path_index * 72;
    trigger_time_ms = path_index * 900 + 500;
    quest_entry_original_t *spawn = &builder.spawns[entry_count];
    spawn->pos = quest_vec2_t((float)x, 688.0f);
